1	import { readFileSync } from "node:fs";
2	
3	import {
4	  isProtocolProfile,
5	  PROTOCOL_PROFILES,
6	  type ProtocolProfile,
7	  parseCanonicalScope,
8	} from "@bdp/protocol";
9	
10	export type { ProtocolProfile } from "@bdp/protocol";
11	
12	export type Mode = "local-test" | "production";
13	
14	/** Report formats a future conformance runner will emit. */
15	export type ReportFormat = "json" | "text";
16	const REPORT_FORMATS: readonly ReportFormat[] = ["json", "text"];
17	
18	/**
19	 * Every role resolves the same shared contract. A role only narrows what may be
20	 * left to a default; it never adds a field or a separate schema. Structural
21	 * validation of the file — top-level section names and nested field names — is
22	 * always global, so a shape mistake stays loud in every role. Content
23	 * validation (grammars, ranges, enums) is role-owned: `ROLE_SECTIONS` records
24	 * which sections a role actually reads, and the loader defers content checks
25	 * for the rest so that an unrelated section's value cannot block an executable
26	 * that does not consume it.
27	 */
28	export type Role = "bdp" | "bdptest" | "bdpbd" | "conformance";
29	
30	export interface ServerReadLimitsConfig {
31	  readonly page: {
32	    readonly defaultItems: number;
33	    readonly maximumItems: number;
34	  };
35	  readonly selector: {
36	    readonly bytes: number;
37	    readonly depth: number;
38	    readonly nodes: number;
39	  };
40	  readonly cursorTtlMilliseconds: number;
41	}
42	
43	/** Public defaults used by both shipping server compositions and conformance. */
44	export const DEFAULT_SERVER_READ_LIMITS: ServerReadLimitsConfig = Object.freeze({
45	  page: Object.freeze({ defaultItems: 50, maximumItems: 200 }),
46	  selector: Object.freeze({ bytes: 16_384, depth: 32, nodes: 256 }),
47	  cursorTtlMilliseconds: 300_000,
48	});
49	
50	/** Public safety ceilings for operator-configurable server Read limits. */
51	export const MAXIMUM_SERVER_READ_LIMITS: ServerReadLimitsConfig = Object.freeze({
52	  page: Object.freeze({ defaultItems: 1_000, maximumItems: 10_000 }),
53	  selector: Object.freeze({ bytes: 65_536, depth: 128, nodes: 4_096 }),
54	  cursorTtlMilliseconds: 86_400_000,
55	});
56	
57	/**
58	 * The full shared contract, as it appears when no role is passed. Each
59	 * role-specific view below is a `Pick` of these same section types, so the
60	 * shape stays coherent across roles.
61	 */
62	export interface StartupConfig {
63	  readonly mode: Mode;
64	  readonly scope: { readonly url: string };
65	  readonly auth: { readonly token?: string };
66	  readonly server: {
67	    readonly host: string;
68	    readonly port: number;
69	    readonly advertisedProfile?: ProtocolProfile;
70	    readonly limits: ServerReadLimitsConfig;
71	    /**
72	     * Conformance launch flag: the one absolute resource URL whose read must
73	     * fail with a private internal fault. Composition roots wrap their Scope
74	     * port with a faulting proxy when this is set. It configures diagnostics
75	     * only and grants nothing: admission, profiles, and every other route are
76	     * untouched, and the injected detail never crosses the wire.
77	     */
78	    readonly internalFaultResource?: string;
79	  };
80	  readonly bd: { readonly executable: string; readonly workspace?: string };
81	  readonly bdptest: { readonly fixture?: string };
82	  readonly conformance: {
83	    readonly profile: ProtocolProfile;
84	    readonly scenarioFilter?: string;
85	    readonly seed: number;
86	    readonly reportFormat: ReportFormat;
87	  };
88	}
89	
90	export type BdpStartupConfig = Pick<StartupConfig, "mode" | "scope" | "auth">;
91	export type BdptestStartupConfig = Pick<StartupConfig, "mode" | "scope" | "server" | "bdptest">;
92	export type BdpbdStartupConfig = Pick<StartupConfig, "mode" | "scope" | "server" | "bd">;
93	export type ConformanceStartupConfig = Pick<
94	  StartupConfig,
95	  "mode" | "scope" | "auth" | "conformance"
96	>;
97	
98	export interface ConfigIssue {
99	  readonly path: string;
100	  readonly message: string;
101	}
102	
103	export class ConfigError extends Error {
104	  readonly issues: readonly ConfigIssue[];
105	
106	  constructor(issues: readonly ConfigIssue[]) {
107	    super(`invalid startup configuration (${issues.length} issue(s))`);
108	    this.name = "ConfigError";
109	    this.issues = issues;
110	  }
111	}
112	
113	export interface ServerReadUpdateLimitsConfig {
114	  readonly requestBodyBytes: number;
115	  readonly propertiesBytes: number;
116	  readonly diagnosticBytes: number;
117	}
118	
119	/** Reference mutation defaults. No current CLI/file/HTTP consumer or profile grant. */
120	export const DEFAULT_SERVER_READ_UPDATE_LIMITS: ServerReadUpdateLimitsConfig = Object.freeze({
121	  requestBodyBytes: 1_048_576,
122	  propertiesBytes: 1_048_576,
123	  diagnosticBytes: 8_388_608,
124	});
125	
126	/** Explicit receiving API, separate from StartupConfig's shipping Read limits.
127	 * Only own enumerable data fields supply overrides; accessors are never invoked.
128	 * This resolves numbers, not jointly feasible startup/retained-state qualification.
129	 */
130	export function resolveServerReadUpdateLimits(
131	  input?: Partial<ServerReadUpdateLimitsConfig>,
132	): ServerReadUpdateLimitsConfig {
133	  const path = "server.readUpdateLimits";
134	  if (input === undefined) return DEFAULT_SERVER_READ_UPDATE_LIMITS;
135	  if (
136	    input === null ||
137	    typeof input !== "object" ||
138	    (Object.getPrototypeOf(input) !== Object.prototype && Object.getPrototypeOf(input) !== null)
139	  )
140	    throw new ConfigError([{ path, message: `${path} must be a plain record` }]);
141	  const result = { ...DEFAULT_SERVER_READ_UPDATE_LIMITS };
142	  const issues: ConfigIssue[] = [];
143	  for (const key of Reflect.ownKeys(input)) {
144	    const descriptor = Object.getOwnPropertyDescriptor(input, key);
145	    if (
146	      (key !== "requestBodyBytes" && key !== "propertiesBytes" && key !== "diagnosticBytes") ||
147	      !descriptor?.enumerable ||
148	      !("value" in descriptor)
149	    ) {
150	      issues.push({ path, message: `${path} accepts only its three enumerable data fields` });
151	      continue;
152	    }
153	    const value: unknown = descriptor.value;
154	    if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 1)
155	      issues.push({ path: `${path}.${key}`, message: `${key} must be a positive safe integer` });
156	    else result[key] = value;
157	  }
158	  if (issues.length) throw new ConfigError(issues);
159	  return Object.freeze(result);
160	}
161	
162	const DEFAULT_HOST = "127.0.0.1";
163	const DEFAULT_PORT = 8080;
164	const DEFAULT_PAGE_ITEMS = DEFAULT_SERVER_READ_LIMITS.page.defaultItems;
165	const DEFAULT_MAXIMUM_PAGE_ITEMS = DEFAULT_SERVER_READ_LIMITS.page.maximumItems;
166	const SELECTOR_BYTES = DEFAULT_SERVER_READ_LIMITS.selector.bytes;
167	const SELECTOR_DEPTH = DEFAULT_SERVER_READ_LIMITS.selector.depth;
168	const SELECTOR_NODES = DEFAULT_SERVER_READ_LIMITS.selector.nodes;
169	const CURSOR_TTL_MILLISECONDS = DEFAULT_SERVER_READ_LIMITS.cursorTtlMilliseconds;
170	
171	/** Reserved first path segment. Production refuses it on any host. */
172	const LOCAL_TEST_SEGMENT = "local-test";
173	
174	/** The local-test Scope URL under the default host and port. */
175	export const LOCAL_TEST_SCOPE_URL = localTestScopeUrl(DEFAULT_HOST, DEFAULT_PORT);
176	export const REDACTED = "<redacted>";
177	
178	const FIELDS = [
179	  "mode",
180	  "scope.url",
181	  "auth.token",
182	  "server.host",
183	  "server.port",
184	  "server.advertisedProfile",
185	  "server.limits.page.defaultItems",
186	  "server.limits.page.maximumItems",
187	  "server.limits.selector.bytes",
188	  "server.limits.selector.depth",
189	  "server.limits.selector.nodes",
190	  "server.limits.cursorTtlMilliseconds",
191	  "server.internalFaultResource",
192	  "bd.executable",
193	  "bd.workspace",
194	  "bdptest.fixture",
195	  "conformance.profile",
196	  "conformance.scenarioFilter",
197	  "conformance.seed",
198	  "conformance.reportFormat",
199	] as const;
200	
201	type Field = (typeof FIELDS)[number];
202	type Section = "scope" | "auth" | "server" | "bd" | "bdptest" | "conformance";
203	
204	const ENV_VARIABLE: Record<Field, string> = {
205	  mode: "BDP_MODE",
206	  "scope.url": "BDP_SCOPE_URL",
207	  "auth.token": "BDP_AUTH_TOKEN",
208	  "server.host": "BDP_SERVER_HOST",
209	  "server.port": "BDP_SERVER_PORT",
210	  "server.advertisedProfile": "BDP_SERVER_ADVERTISED_PROFILE",
211	  "server.limits.page.defaultItems": "BDP_SERVER_PAGE_DEFAULT_ITEMS",
212	  "server.limits.page.maximumItems": "BDP_SERVER_PAGE_MAXIMUM_ITEMS",
213	  "server.limits.selector.bytes": "BDP_SERVER_SELECTOR_BYTES",
214	  "server.limits.selector.depth": "BDP_SERVER_SELECTOR_DEPTH",
215	  "server.limits.selector.nodes": "BDP_SERVER_SELECTOR_NODES",
216	  "server.limits.cursorTtlMilliseconds": "BDP_SERVER_CURSOR_TTL_MILLISECONDS",
217	  "server.internalFaultResource": "BDP_SERVER_INTERNAL_FAULT_RESOURCE",
218	  "bd.executable": "BDP_BD_EXECUTABLE",
219	  "bd.workspace": "BDP_BD_WORKSPACE",
220	  "bdptest.fixture": "BDP_BDPTEST_FIXTURE",
221	  "conformance.profile": "BDP_CONFORMANCE_PROFILE",
222	  "conformance.scenarioFilter": "BDP_CONFORMANCE_SCENARIO_FILTER",
223	  "conformance.seed": "BDP_CONFORMANCE_SEED",
224	  "conformance.reportFormat": "BDP_CONFORMANCE_REPORT_FORMAT",
225	};
226	
227	const KNOWN_SECTIONS: ReadonlySet<Section> = new Set<Section>([
228	  "scope",
229	  "auth",
230	  "server",
231	  "bd",
232	  "bdptest",
233	  "conformance",
234	]);
235	const FIELD_SET = new Set<string>(FIELDS);
236	
237	/**
238	 * Which sections each role actually reads. Sections outside this set are
239	 * silently ignored for that role: file values in those sections are stored
240	 * unvalidated (their content is never checked and never appears in the
241	 * returned view), and env values are not consulted — with one field-level
242	 * exception. When a role does not own `server` but is going to derive the
243	 * local-test Scope URL (mode is `local-test` and `scope.url` is absent),
244	 * `server.host` and `server.port` are still read from every source so all
245	 * roles agree on the derived identity; see `loadStartupConfig` for the
246	 * dependency. Structural vocabulary — unknown top-level sections and unknown
247	 * nested field names — is validated globally by the file parser, so a typo
248	 * like `bdptest.fixtre` cannot hide under an unrelated role. See "Loudness"
249	 * in `docs/design/startup-configuration.md` for the split.
250	 */
251	const ROLE_SECTIONS: Record<Role, ReadonlySet<Section>> = {
252	  bdp: new Set<Section>(["scope", "auth"]),
253	  bdptest: new Set<Section>(["scope", "server", "bdptest"]),
254	  bdpbd: new Set<Section>(["scope", "server", "bd"]),
255	  conformance: new Set<Section>(["scope", "auth", "conformance"]),
256	};
257	
258	export interface ParsedConfigArgs {
259	  readonly configFile: string | undefined;
260	  readonly rest: readonly string[];
261	  readonly errors: readonly string[];
262	}
263	
264	/** Split `--config <path>` out of an argv slice, leaving every other argument untouched. */
265	export function parseConfigArgs(argv: readonly string[]): ParsedConfigArgs {
266	  const rest: string[] = [];
267	  const errors: string[] = [];
268	  let configFile: string | undefined;
269	  let seen = false;
270	
271	  const assign = (value: string): void => {
272	    if (value === "") errors.push("--config requires a non-empty path");
273	    else if (seen) errors.push("--config may be given only once");
274	    else {
275	      configFile = value;
276	      seen = true;
277	    }
278	  };
279	
280	  for (let index = 0; index < argv.length; index += 1) {
281	    const argument = argv[index] ?? "";
282	    if (argument === "--config") {
283	      const value = argv[index + 1];
284	      if (value === undefined || value.startsWith("--")) errors.push("--config requires a path");
285	      else {
286	        assign(value);
287	        index += 1;
288	      }
289	    } else if (argument.startsWith("--config=")) {
290	      assign(argument.slice("--config=".length));
291	    } else {
292	      rest.push(argument);
293	    }
294	  }
295	
296	  return { configFile, rest, errors };
297	}
298	
299	export interface LoadOptions {
300	  readonly configFile?: string | undefined;
301	  readonly env: NodeJS.ProcessEnv;
302	  readonly readFile?: (path: string) => string;
303	  /**
304	   * Restricts validation and output to sections the role reads. Omitting it
305	   * loads the full shared contract, which is the test seam that proves every
306	   * field parses coherently in isolation.
307	   */
308	  readonly role?: Role;
309	}
310	
311	/**
312	 * Resolve startup configuration from environment variables, then an optional JSON
313	 * file, then compiled-in local-test defaults. Precedence and names are pinned in
314	 * docs/design/startup-configuration.md.
315	 *
316	 * When a role is supplied, only the sections that role owns are *validated for
317	 * content* and *emitted*. But structural vocabulary (top-level sections and
318	 * nested field names) is validated globally by the file parser, so a nested
319	 * typo like `{"bdptest":{"fixtre":"x"}}` is still surfaced when loading as
320	 * `bdp`. A single field-level dependency exists: `server.host` and
321	 * `server.port` are consulted by *any* role when they contribute to the
322	 * derived local-test Scope URL — otherwise a shared local-test configuration
323	 * where the port is `9000` would let `bdptest` derive port 9000 while `bdp`
324	 * dialed port 8080, breaking the one-identity contract.
325	 */
326	export function loadStartupConfig(options: LoadOptions & { role: "bdp" }): BdpStartupConfig;
327	export function loadStartupConfig(options: LoadOptions & { role: "bdptest" }): BdptestStartupConfig;
328	export function loadStartupConfig(options: LoadOptions & { role: "bdpbd" }): BdpbdStartupConfig;
329	export function loadStartupConfig(
330	  options: LoadOptions & { role: "conformance" },
331	): ConformanceStartupConfig;
332	export function loadStartupConfig(options: LoadOptions & { role?: undefined }): StartupConfig;
333	export function loadStartupConfig(
334	  options: LoadOptions,
335	):
336	  | StartupConfig
337	  | BdpStartupConfig
338	  | BdptestStartupConfig
339	  | BdpbdStartupConfig
340	  | ConformanceStartupConfig {
341	  const activeSections: ReadonlySet<Section> =
342	    options.role === undefined ? KNOWN_SECTIONS : ROLE_SECTIONS[options.role];
343	
344	  const issues: ConfigIssue[] = [];
345	  const configFile = selectConfigFile(options, issues);
346	  // Structural vocabulary validation is global; content validation is
347	  // deferred to the per-field consumption below.
348	  const fromFile =
349	    configFile === undefined
350	      ? new Map<Field, unknown>()
351	      : readConfigFile(configFile, options.readFile ?? defaultReadFile, issues);
352	
353	  const rawRead = (field: Field): { value: unknown; explicit: boolean } => {
354	    const fromEnv = options.env[ENV_VARIABLE[field]];
355	    if (fromEnv !== undefined) return { value: fromEnv, explicit: true };
356	    if (fromFile.has(field)) return { value: fromFile.get(field), explicit: true };
357	    return { value: undefined, explicit: false };
358	  };
359	
360	  // Every role consumes `mode` and `scope.url`. We read them first because the
361	  // derivation rule below depends on both.
362	  const mode = readMode(rawRead("mode").value, issues);
363	  const scopeUrl = rawRead("scope.url");
364	  const scopeExplicit = scopeUrl.explicit;
365	
366	  const serverOwned = activeSections.has("server");
367	  // Field-level dependency: `server.host` and `server.port` are shared inputs
368	  // to the derived local-test Scope URL. Whenever that derivation is going to
369	  // fire, every role must consult them so all four role views resolve to the
370	  // same Scope. When `scope.url` is explicit, the derivation is skipped and
371	  // non-server roles ignore host/port entirely, preserving role isolation.
372	  const hostPortConsulted = serverOwned || (!scopeExplicit && mode === "local-test");
373	  const host = hostPortConsulted ? readHost(rawRead("server.host").value, issues) : DEFAULT_HOST;
374	  const port = hostPortConsulted ? readPort(rawRead("server.port").value, issues) : DEFAULT_PORT;
375	
376	  // `server.advertisedProfile` is server-only: an invalid value in a
377	  // non-server role's environment must not block startup.
378	  const advertisedProfile = serverOwned
379	    ? readOptionalProfile(rawRead("server.advertisedProfile").value, issues)
380	    : undefined;
381	  const pageDefaultItems = serverOwned
382	    ? readBoundedPositiveInteger(
383	        "server.limits.page.defaultItems",
384	        rawRead("server.limits.page.defaultItems").value,
