965	function inPortRange(port: number): boolean {
966	  return Number.isInteger(port) && port >= 0 && port <= 65535;
967	}
968	
969	/**
970	 * A Scope URL is the deployment's canonical identity, so it is stored in one
971	 * serialization: `URL` normalization plus a trailing slash, which makes relative
972	 * resolution against it unambiguous. Spelling differences a URL parser erases —
973	 * scheme and host case, a written-out default port — are normalized rather than
974	 * refused. Parts that would make two deployments disagree about identity, or that
975	 * carry a secret, are refused. Returns undefined once it has recorded why.
976	 *
977	 * No message echoes the value. A Scope URL that failed to parse is exactly the
978	 * case where it may not be a URL at all — a shell-mangled line, or a token pasted
979	 * into the wrong variable — and these issues are written to stderr on startup.
980	 */
981	function readScopeUrl(value: unknown, issues: ConfigIssue[]): string | undefined {
982	  const push = (message: string): void => {
983	    issues.push({ path: "scope.url", message });
984	  };
985	  if (typeof value !== "string" || value.length === 0) {
986	    push("scope.url must be a non-empty string");
987	    return undefined;
988	  }
989	  if (!/^[A-Za-z][A-Za-z0-9+.-]*:\/\/[^/?#]+/.test(value)) {
990	    push("scope.url must be an absolute URL");
991	    return undefined;
992	  }
993	
994	  const originalPath = /^[A-Za-z][A-Za-z0-9+.-]*:\/\/[^/?#]*([^?#]*)/.exec(value)?.[1];
995	
996	  let url: URL;
997	  try {
998	    url = new URL(value);
999	  } catch {
1000	    push("scope.url must be an absolute URL");
1001	    return undefined;
1002	  }
1003	
1004	  if (url.protocol !== "http:" && url.protocol !== "https:") {
1005	    push("scope.url must use http or https");
1006	    return undefined;
1007	  }
1008	  if (
1009	    originalPath !== undefined &&
1010	    originalPath !== url.pathname &&
1011	    !(originalPath === "" && url.pathname === "/")
1012	  ) {
1013	    push("scope.url must use canonical path encoding");
1014	    return undefined;
1015	  }
1016	
1017	  let refused = false;
1018	  if (url.username !== "" || url.password !== "") {
1019	    push("scope.url must not embed credentials");
1020	    refused = true;
1021	  }
1022	  if (url.search !== "" || url.hash !== "") {
1023	    push("scope.url must not carry a query string or fragment");
1024	    refused = true;
1025	  }
1026	  if (refused) return undefined;
1027	
1028	  if (!url.pathname.endsWith("/")) url.pathname = `${url.pathname}/`;
1029	  try {
1030	    parseCanonicalScope(url.href);
1031	  } catch {
1032	    push("scope.url must use canonical path encoding");
1033	    return undefined;
1034	  }
1035	  return url.href;
1036	}
1037	
1038	type MaybeAuthSection = { readonly auth?: { readonly token?: string } };
1039	
1040	/**
1041	 * Copy `config` with the bearer token replaced, for anything that leaves the
1042	 * process. Accepts every role's view: server-only views have no `auth`
1043	 * section, so they are returned unchanged.
1044	 */
1045	export function redactStartupConfig<C extends object>(config: C): C {
1046	  const auth = (config as MaybeAuthSection).auth;
1047	  if (auth?.token === undefined) return config;
1048	  return { ...config, auth: { ...auth, token: REDACTED } };
1049	}
1050	
1051	export function formatStartupDiagnostic(config: object, executable: string): string {
1052	  return `${JSON.stringify({
1053	    level: "info",
1054	    event: "startup.config",
1055	    executable,
1056	    config: redactStartupConfig(config),
1057	  })}\n`;
1058	}
1059	
1060	export function formatConfigError(error: ConfigError, executable: string): string {
1061	  return `${JSON.stringify({
1062	    level: "error",
1063	    event: "startup.config_error",
1064	    executable,
1065	    issues: error.issues,
1066	  })}\n`;
1067	}
