3	/** Lossless JSON syntax, separate from per-operation BDP numeric admission.
4	 * The caller bounds transport bytes. This iterative parser imposes no hidden
5	 * nesting/wire limit and never constructs a rounded executable number.
6	 */
7	export class JsonSyntaxError extends SyntaxError {
8	  constructor(
9	    message: string,
10	    readonly offset: number,
11	  ) {
12	    super(`${message} at JSON offset ${offset}`);
13	    this.name = "JsonSyntaxError";
14	  }
15	}
16	
17	export class JsonNumberLiteral {
18	  constructor(readonly literal: string) {
19	    if (!JSON_NUMBER.test(literal)) throw new TypeError("invalid JSON number literal");
20	    Object.freeze(this);
21	  }
22	}
23	export type LosslessJsonValue =
24	  | null
25	  | boolean
26	  | string
27	  | JsonNumberLiteral
28	  | readonly LosslessJsonValue[]
29	  | { readonly [key: string]: LosslessJsonValue };
30	export type AdmittedJsonValue =
31	  | null
32	  | boolean
33	  | string
34	  | number
35	  | readonly AdmittedJsonValue[]
36	  | { readonly [key: string]: AdmittedJsonValue };
37	export interface JsonNumberOccurrence {
38	  readonly pointer: string;
39	  readonly literal: string;
40	}
41	/** Occurrences are relative to the supplied document/operation. The caller supplies
42	 * the actual wire entry, including its properties-relative location when required;
43	 * it must obtain any needed operation context separately. The server's paired
44	 * create adapter performs that mapping before accounting. Bare callers still own it.
45	 * Bounds count entries and UTF-8 bytes of the serialized list, not
46	 * internal occurrences. Omitting both bounds explicitly requests the full list.
47	 */
48	export interface JsonNumberDiagnosticBudget {
49	  readonly diagnostics?: number;
50	  readonly diagnosticBytes?: number;
51	  readonly diagnostic: (occurrence: JsonNumberOccurrence) => ValidationDiagnostic;
52	}
53	/** A local caller/configuration failure, never a BDP wire error code. The caller
54	 * must configure a feasible advertised budget for every permitted request;
55	 * transport integration must not expose this as an unhandled input exception.
56	 */
57	export class JsonDiagnosticBudgetError extends RangeError {
58	  constructor(message: string) {
59	    super(message);
60	    this.name = "JsonDiagnosticBudgetError";
61	  }
62	}
