7	export function moduleSpecifiers(contents, fileName = "source.ts") {
8	  const program = parseProgram(contents, fileName);
9	  const createRequireFactories = new Set(["createRequire"]);
10	  const moduleNamespaces = new Set();
11	  const requireFunctions = new Set(["require"]);
12	
13	  walk(program, (node) => {
14	    if (node.type !== "ImportDeclaration" || !nodeModuleSpecifiers.has(node.source.value)) return;
15	    for (const specifier of node.specifiers) {
16	      if (
17	        specifier.type === "ImportNamespaceSpecifier" ||
18	        specifier.type === "ImportDefaultSpecifier"
19	      )
20	        moduleNamespaces.add(specifier.local.name);
21	      else if (
22	        specifier.type === "ImportSpecifier" &&
23	        importedName(specifier.imported) === "createRequire"
24	      )
25	        createRequireFactories.add(specifier.local.name);
26	    }
27	    return;
28	  });
29	  walk(program, (node) => {
30	    if (
31	      node.type === "TSImportEqualsDeclaration" &&
32	      node.id.type === "Identifier" &&
33	      node.moduleReference.type === "TSExternalModuleReference" &&
34	      node.moduleReference.expression.type === "StringLiteral" &&
35	      nodeModuleSpecifiers.has(node.moduleReference.expression.value)
36	    )
37	      moduleNamespaces.add(node.id.name);
38	  });
39	
40	  collectRequireFunctions(program, requireFunctions, createRequireFactories, moduleNamespaces);
41	
42	  const specifiers = new Set();
43	  walk(program, (node) => {
44	    if (
45	      node.type === "ImportDeclaration" ||
46	      node.type === "ExportNamedDeclaration" ||
47	      node.type === "ExportAllDeclaration"
48	    ) {
49	      addLiteral(specifiers, node.source);
50	    } else if (node.type === "ImportExpression") {
51	      addLiteral(specifiers, node.source);
52	    } else if (node.type === "TSImportType") {
53	      addLiteral(specifiers, node.source ?? node.argument);
54	    } else if (node.type === "TSExternalModuleReference") {
55	      addLiteral(specifiers, node.expression);
56	    } else if (node.type === "CallExpression") {
57	      const identifierRequire =
58	        node.callee.type === "Identifier" && requireFunctions.has(node.callee.name);
59	      const requireResolve =
60	        node.callee.type === "MemberExpression" &&
61	        node.callee.object.type === "Identifier" &&
62	        requireFunctions.has(node.callee.object.name) &&
63	        memberName(node.callee) === "resolve";
64	      const immediateCreateRequire =
65	        node.callee.type === "CallExpression" &&
66	        isCreateRequireFactoryCall(node.callee, createRequireFactories, moduleNamespaces);
