409	function createCanonicalHttpRequest(
410	  scope: AbsoluteHttpUrl,
411	  requestTarget: string | undefined,
412	  options: NodeHttpRequestOptions = {},
413	): Request {
414	  const target = requestTarget ?? "/";
415	  const canonicalOrigin = `${new URL(scope).origin}/`;
416	  const pathAndQuery = normalizationSafeRawRequestPath(target);
417	  const canonical = new URL(pathAndQuery ?? ".bdp-invalid-request-target", canonicalOrigin);
418	  return new Request(canonical, {
419	    ...(options.method === undefined ? {} : { method: options.method }),
420	    ...(options.signal === undefined ? {} : { signal: options.signal }),
421	    ...(options.headers === undefined ? {} : { headers: options.headers }),
422	  });
