425	function nodeRequestHeaders(rawHeaders: readonly string[]): Headers {
426	  const headers = new Headers();
427	  for (let index = 0; index + 1 < rawHeaders.length; index += 2) {
428	    const name = rawHeaders[index];
429	    const value = rawHeaders[index + 1];
430	    if (name !== undefined && value !== undefined) headers.append(name, value);
431	  }
432	  return headers;
