519	/** Binds a verified listener and keeps later listener failures structured. */
520	export function listenNodeHttpServer(
521	  listener: NodeHttpServer,
522	  options: NodeHttpListenOptions,
523	): Promise<void> {
524	  if (!verifiedNodeHttpServers.has(listener)) {
525	    throw new TypeError("listenNodeHttpServer requires a listener created by createNodeHttpServer");
526	  }
527	  if (boundNodeHttpServers.has(listener)) {
528	    throw new TypeError("listenNodeHttpServer may bind each listener only once");
529	  }
530	  boundNodeHttpServers.add(listener);
531	  return new Promise((resolve, reject) => {
532	    const onBindError = (error: unknown): void => {
533	      boundNodeHttpServers.delete(listener);
534	      listener.removeListener("error", onBindError);
535	      listener.removeListener("listening", onListening);
536	      reject(new NodeHttpListenerError(error));
537	    };
538	    const onListening = (): void => {
539	      listener.removeListener("error", onBindError);
540	      listener.on("error", (error) => options.onError(new NodeHttpListenerError(error)));
541	      resolve();
542	    };
543	    listener.once("error", onBindError);
544	    listener.once("listening", onListening);
545	    try {
546	      listener.listen(options.port, options.host);
547	    } catch (error) {
548	      onBindError(error);
549	    }
550	  });
551	}
