636	function createProcessTerminationSignal(): {
637	  readonly signal: AbortSignal;
638	  readonly dispose: () => void;
639	} {
640	  const controller = new AbortController();
641	  const stop = (signal: "SIGINT" | "SIGTERM"): void => controller.abort(signal);
642	  process.once("SIGINT", stop);
643	  process.once("SIGTERM", stop);
644	  return {
645	    signal: controller.signal,
646	    dispose: () => {
647	      process.off("SIGINT", stop);
648	      process.off("SIGTERM", stop);
649	    },
650	  };
651	}
652	
653	function observeTermination(signal: AbortSignal): {
654	  readonly promise: Promise<"SIGINT" | "SIGTERM">;
655	  readonly dispose: () => void;
656	} {
657	  let stop: (() => void) | undefined;
658	  const promise = new Promise<"SIGINT" | "SIGTERM">((resolve, reject) => {
659	    stop = (): void => {
660	      if (signal.reason === "SIGINT" || signal.reason === "SIGTERM") resolve(signal.reason);
661	      else reject(new TypeError("termination signal reason must be SIGINT or SIGTERM"));
662	    };
663	    if (signal.aborted) stop();
664	    else signal.addEventListener("abort", stop, { once: true });
665	  });
666	  return {
667	    promise,
668	    dispose: () => {
669	      if (stop !== undefined) signal.removeEventListener("abort", stop);
670	    },
671	  };
672	}
