674	export function createHttpHandler(server: ReadServer): HttpHandler {
675	  if (!verifiedReadServers.has(server)) {
676	    throw new TypeError("createHttpHandler requires a server created by createReadServer");
677	  }
678	  const route = createReadHttpRoute({
679	    scope: server.scope,
680	    probe: (request) => server.probe({ signal: request.signal, httpRequest: request }),
681	    problem: problemResponse,
682	    async discover(request) {
683	      const result = await server.perform(
684	        { kind: "scope-discovery", scope: server.scope },
685	        { signal: request.signal, httpRequest: request },
686	      );
687	      return isReadServerProblem(result) ? problemResponse(result) : jsonResponse(result);
688	    },
689	    async alias(aliasPath, request) {
690	      // Gate before consulting the static table, even for invalid alias paths.
691	      const gate = await server.perform(
692	        { kind: "scope-discovery", scope: server.scope },
693	        { signal: request.signal, httpRequest: request },
694	      );
695	      if (isReadServerProblem(gate)) return problemResponse(gate);
696	      if (isReadProblem(aliasPath)) return problemResponse(aliasPath);
697	      const target = server.aliases?.get(aliasPath) ?? notFound();
698	      return isReadProblem(target)
699	        ? problemResponse(target)
700	        : { status: 307, headers: new Headers({ location: target, "content-length": "0" }) };
701	    },
702	    async perform(parsed, request) {
703	      const result = await server.perform(parsed, {
704	        signal: request.signal,
705	        httpRequest: request,
706	      });
707	      return isReadServerProblem(result)
708	        ? problemResponse(result)
709	        : scopeDataResponse(parsed, result);
710	    },
711	  });
712	  return async (request) => {
713	    let response: HttpResponse;
714	    try {
715	      response = await route(request);
716	    } catch (error) {
717	      if (error instanceof ScopeServerLocalError) {
718	        if (error.code === "operation-aborted") {
719	          throw error;
720	        }
721	        response = problemResponse(readProblem("temporarily-unavailable", error.message));
722	      } else throw error;
723	    }
724	    return applyReadHttpSemantics(request, response);
725	  };
