730	  const status = definition.status;
731	  if (problem.status !== undefined && problem.status !== status)
732	    throw new TypeError("Read Problem status does not match its code");
733	  if (problem.type !== definition.type)
734	    throw new TypeError("Read Problem type does not match its code");
735	  if (problem.retry !== definition.retry)
736	    throw new TypeError("Read Problem retry does not match its code");
737	  const headers = new Headers({
738	    "content-type": "application/problem+json",
739	    "cache-control": "private, no-store",
